:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-panel: #f5f5f5;
  --color-pebble-wash: #f0f0f0;
  --color-onyx-badge: #000000;
  --color-jet-ink: #171717;
  --color-graphite-caption: #737373;
  --color-ash-whisper: #a3a3a3;
  --color-smoke-hairline: #0000001a;
  --color-sprout-signal: #22c55e;
  --color-cinder-alarm: #ef4444;
  --color-ember-spark: #fd4801;
  --color-sunbeam-highlight: #fef3c7;
  --color-umber-ink: #451a03;

  /* Typography — Font Families */
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-ui-monospace: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-emoji: "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.333;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.429;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.8;
  --tracking-body: 0px;
  --text-body-lg: 17px;
  --leading-body-lg: 1.625;
  --tracking-body-lg: 0px;
  --text-subheading: 22.4px;
  --leading-subheading: 1.5;
  --tracking-subheading: -0.4px;
  --text-heading: 28.8px;
  --leading-heading: 1.2;
  --tracking-heading: -0.5px;
  --text-display: 64px;
  --leading-display: 1;
  --tracking-display: -1.8px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-30: 30px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;
  --spacing-144: 144px;

  /* Layout */
  --layout-max-width: 1280px;
  --layout-content-width: 672px;
  --layout-section-gap: 144px;
  --layout-card-padding: 16px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-md-2: 7px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 18px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-pills: 9999px;
  --radius-buttons: 9999px;
  --radius-avatars: 9999px;
  --radius-tags: 9999px;
  --radius-badges: 9999px;
  --radius-small-elements: 6px;
  --radius-small-cards: 8px;
  --radius-inner-tiles: 7px;
  --radius-images: 4px;
  --radius-cards: 12px;
  --radius-sections: 18px;

  /* Shadows */
  --shadow-subtle: 0px 1px 2px 0px rgba(0, 0, 0, 0.05);
  --shadow-subtle-2: inset 0px 0.5px 0px 0px rgba(255, 255, 255, 0.32);
  --shadow-sm: 0px 1px 1px -1px rgba(0, 0, 0, 0.08), 0px 2px 2px -1px rgba(0, 0, 0, 0.08), 0px 0px 0px 1px rgba(0, 0, 0, 0.06), inset 0px 1px 0px 0px #ffffff, inset 0px 1px 2px 1px #ffffff, inset 0px 1px 2px 0px rgba(0, 0, 0, 0.06);
  --shadow-md: 0px 3px 6px -3px rgba(0, 0, 0, 0.05), 0px 2px 4px -2px rgba(0, 0, 0, 0.05), 0px 1px 2px -1px rgba(0, 0, 0, 0.05), 0px 1px 1px -1px rgba(0, 0, 0, 0.05), 0px 1px 0px -1px rgba(0, 0, 0, 0.05);
  --shadow-lg: inset 0px 0.5px 0px 0px rgba(0, 0, 0, 0.1), 0px 2px 4px 0px rgba(0, 0, 0, 0.1), 0px 4px 12px 0px rgba(0, 0, 0, 0.1), 0px 8px 20px 0px rgba(0, 0, 0, 0.02);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-panel: #f5f5f5;
  --surface-pebble-wash: #f0f0f0;
  --surface-onyx-badge: #000000;
}

